import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Dude, wheres my cluster?","description":"","frontmatter":{"title":"Dude, wheres my cluster?","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","分布式存储","存储集群","性能优化","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Dude_where_s_my_cluster.md","filePath":"posts/2026/Dude_where_s_my_cluster.md","lastUpdated":null}'),l={name:"posts/2026/Dude_where_s_my_cluster.md"};function r(n,a,h,o,p,d){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由来自 Wellcome Sanger Institute 的 Dave Holland 主讲，介绍了如何在不中断服务的情况下，将一个运行中的大规模 Ceph 存储集群从一组数据中心机柜迁移到另外两个数据中心房间。整个迁移历时约四到五个月，涉及超过 3,000 个 OSD、15 PB 原始容量的生产级集群。</p><h2 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍&quot;">​</a></h2><h3 id="wellcome-sanger-institute-简介" tabindex="-1">Wellcome Sanger Institute 简介 <a class="header-anchor" href="#wellcome-sanger-institute-简介" aria-label="Permalink to &quot;Wellcome Sanger Institute 简介&quot;">​</a></h3><p>Wellcome Sanger Institute 位于英国剑桥南部 Hinxton，成立于 1990 年代，是人类基因组计划的重要参与机构之一。该计划耗时十余年，完成了人类基因组三十亿碱基对（A、C、G、T）的测序工作。目前研究所仍持续进行大规模 DNA 测序，数据规模极大，是 Ceph 存储系统的主要驱动力。</p><h3 id="ceph-集群现状" tabindex="-1">Ceph 集群现状 <a class="header-anchor" href="#ceph-集群现状" aria-label="Permalink to &quot;Ceph 集群现状&quot;">​</a></h3><ul><li>原始容量：15 PB，采用三副本（three-way replication）策略</li><li>OSD 数量：超过 3,000 个</li><li>版本：仍在使用 Ceph 16 Pacific（较旧版本）</li><li>部署方式：与 OpenStack 私有云深度集成，共用同一批机柜</li><li>对外服务：通过 RGW（RADOS Gateway）提供 S3 接口，HAProxy 做负载均衡，已对互联网开放</li><li>管理工具：使用 ceph-ansible（现已基本废弃）</li></ul><p>S3/RGW 的使用远超预期——最初只是 OpenStack 的附属，结果成为研究所最核心的存储服务。科研人员将其用于数据集托管和共享，甚至在不知不觉中承担了 COVID-19 测序数据向英国政府传输的任务。</p><h2 id="迁移动因" tabindex="-1">迁移动因 <a class="header-anchor" href="#迁移动因" aria-label="Permalink to &quot;迁移动因&quot;">​</a></h2><ol><li><strong>数据中心空间需求</strong>：原有机柜为高功耗机柜（30 kW，可突发至 40 kW），研究所急需腾出空间部署高功耗 GPU 服务器</li><li><strong>能耗优化</strong>：每个满载 Ceph 机柜实际只消耗约 9 kW，但占用了 30 kW 制冷预算，造成约 30% 的制冷浪费</li><li><strong>硬件生命周期</strong>：部分服务器可追溯至 2017 年，6 TB 磁盘正在退市，备件采购成本持续上升，且老旧硬件故障率呈浴盆曲线上升趋势</li><li><strong>集群高可用性维护</strong>：保持服务全程不中断</li></ol><h2 id="迁移方案与关键技术" tabindex="-1">迁移方案与关键技术 <a class="header-anchor" href="#迁移方案与关键技术" aria-label="Permalink to &quot;迁移方案与关键技术&quot;">​</a></h2><h3 id="故障域设计" tabindex="-1">故障域设计 <a class="header-anchor" href="#故障域设计" aria-label="Permalink to &quot;故障域设计&quot;">​</a></h3><p>集群共划分四个 failure domain，分布在同一数据中心的四个独立房间。迁移计划安全地将其中两个 failure domain 移入其他房间。</p><h3 id="网络方案-vxlan" tabindex="-1">网络方案：VxLAN <a class="header-anchor" href="#网络方案-vxlan" aria-label="Permalink to &quot;网络方案：VxLAN&quot;">​</a></h3><p>最关键的技术决策是利用已有的 VxLAN 配置（原为 OpenStack hypervisor 网络使用）来透明迁移 Ceph 节点。</p><ul><li>VxLAN 允许在不同路由域之间延伸 VLAN，被迁移节点保持原有 IP 地址和主机名不变</li><li>Ceph 集群对节点位移完全无感知，迁移如同将节点插入同一交换机</li><li>唯一变化是 IPMI/BMC 管理口（不支持 VxLAN 的交换机），需临时重命名主机名，迁移完成后再改回</li></ul><p>这被认为是整个迁移过程中<strong>最大的技术收益</strong>。</p><h3 id="迁移操作流程" tabindex="-1">迁移操作流程 <a class="header-anchor" href="#迁移操作流程" aria-label="Permalink to &quot;迁移操作流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 设置 noout 标志</span></span>
<span class="line"><span>2. 设置 norebalance 标志</span></span>
<span class="line"><span>3. 物理迁移节点</span></span>
<span class="line"><span>4. 恢复标志，让集群自行重平衡</span></span></code></pre></div><p>由于 VxLAN 保证了网络透明性，Ceph 在整个过程中不触发任何数据迁移，操作极为简洁。</p><h3 id="新旧硬件替换策略" tabindex="-1">新旧硬件替换策略 <a class="header-anchor" href="#新旧硬件替换策略" aria-label="Permalink to &quot;新旧硬件替换策略&quot;">​</a></h3><p>对于同步进行的旧硬件替换（将 6 TB 磁盘替换为 18 TB 磁盘），采用简单直接的方案：</p><ul><li>关闭旧节点，安装新节点，让集群自然 rebalance 完成数据迁移</li><li>recovery throttle 参数配置：大部分时间 <code>max_backfills=1</code>、<code>max_active=4</code>，在恢复后期人工适当调高</li><li>每台机器搭载 60 块 18 TB 磁盘，替换原有 60 块 6 TB 磁盘，相当于获得约 3 倍的免费容量升级</li></ul><h2 id="遇到的问题与处理" tabindex="-1">遇到的问题与处理 <a class="header-anchor" href="#遇到的问题与处理" aria-label="Permalink to &quot;遇到的问题与处理&quot;">​</a></h2><h3 id="ceph-ansible-的局限性" tabindex="-1">ceph-ansible 的局限性 <a class="header-anchor" href="#ceph-ansible-的局限性" aria-label="Permalink to &quot;ceph-ansible 的局限性&quot;">​</a></h3><p>ceph-ansible 实际已处于废弃状态，无人维护。其 dynamic inventory 机制导致运行极慢，团队一名成员花费数月尝试优化后放弃。整个迁移过程中这是持续的痛点。</p><h3 id="磁盘故障率上升" tabindex="-1">磁盘故障率上升 <a class="header-anchor" href="#磁盘故障率上升" aria-label="Permalink to &quot;磁盘故障率上升&quot;">​</a></h3><p>搬移旧机器后，磁盘故障率上升约 3 倍，同时出现了 CPU 和内存故障。教训：<strong>搬移老旧机器风险较高</strong>。</p><h3 id="mon-数据库膨胀" tabindex="-1">MON 数据库膨胀 <a class="header-anchor" href="#mon-数据库膨胀" aria-label="Permalink to &quot;MON 数据库膨胀&quot;">​</a></h3><p>迁移过程中，较长时间处于非 <code>HEALTH_OK</code> 状态，导致 MON 数据库的 trimming 暂停，数据库增长至团队有史以来的最大值（演讲中未披露具体数值，但称为&quot;新高分&quot;）。</p><h3 id="网络接线错误" tabindex="-1">网络接线错误 <a class="header-anchor" href="#网络接线错误" aria-label="Permalink to &quot;网络接线错误&quot;">​</a></h3><p>数据中心同事偶尔将 1G 管理网线插入了 IPMI 端口。Ceph 节点的启动脚本已加入健康检查：若 1G 接口不通则拒绝启动 OSD，有效规避了此类问题。</p><h3 id="机柜晃动引发连带故障" tabindex="-1">机柜晃动引发连带故障 <a class="header-anchor" href="#机柜晃动引发连带故障" aria-label="Permalink to &quot;机柜晃动引发连带故障&quot;">​</a></h3><p>搬移 Ceph 机器时，相邻 OpenStack hypervisor 因未完全锁入机架，受到震动后断电。建议采购<strong>带锁扣电源线（latching power leads）</strong>。</p><h3 id="scsi-控制器-multipath-问题" tabindex="-1">SCSI 控制器 multipath 问题 <a class="header-anchor" href="#scsi-控制器-multipath-问题" aria-label="Permalink to &quot;SCSI 控制器 multipath 问题&quot;">​</a></h3><p>新采购的 SCSI 控制器意外启用了 multipath，导致系统识别出双倍磁盘数量。ceph-ansible 无法识别此情况，需要额外编写 multipath 处理脚本，以及更新本地 OSD 替换管理脚本。</p><h3 id="nvme-采购遗漏" tabindex="-1">NVMe 采购遗漏 <a class="header-anchor" href="#nvme-采购遗漏" aria-label="Permalink to &quot;NVMe 采购遗漏&quot;">​</a></h3><p>为 RGW metadata pool 等高 IOPS 场景使用的 NVMe OSD 未被纳入采购计划，不得不从旧机器上回收利用。经监控磨损程度确认仍在 90% 以上，风险可控。</p><h3 id="deep-scrub-积压" tabindex="-1">Deep Scrub 积压 <a class="header-anchor" href="#deep-scrub-积压" aria-label="Permalink to &quot;Deep Scrub 积压&quot;">​</a></h3><p>大量 OSD 的 deep scrub 周期设定为 28 天，但由于长时间处于非健康状态、throttling 和 backfilling 的干扰，积累了大量超期未 scrub 的 PG。解决方案：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查找最久未 scrub 的 PG 并优先处理</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ceph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 按 last_deep_scrub 排序</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ceph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pgi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deep-scrub</span></span></code></pre></div><p>每隔两天人工检查一次积压情况，手动触发优先 scrub，约花费三周时间恢复至 28 天窗口内。</p><h3 id="迁移周期偏长" tabindex="-1">迁移周期偏长 <a class="header-anchor" href="#迁移周期偏长" aria-label="Permalink to &quot;迁移周期偏长&quot;">​</a></h3><p>整个项目历时四至五个月，属于低优先级项目，记录管理不够严谨，加之研究所圣诞假期变更冻结期无法操作，导致整体拖延。</p><h2 id="成果与收益" tabindex="-1">成果与收益 <a class="header-anchor" href="#成果与收益" aria-label="Permalink to &quot;成果与收益&quot;">​</a></h2><ul><li>所有机器迁移完毕，最旧的硬件已替换，集群全程保持运行</li><li>端到端可用性监测（S3 put/list/get + checksum 验证）显示：<strong>迁移操作本身未造成任何可用性损失</strong>；唯一出现的故障由慢盘引发（商用硬件对慢盘处理能力较弱，Ceph 未能及时驱逐相关 OSD）</li><li>磁盘容量从 6 TB 升级至 18 TB，获得额外容量提升，未来有望下线部分节点，进一步降低能耗</li></ul><h2 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h2><ol><li><strong>迁移至 Cephadm</strong>：彻底告别 ceph-ansible，关注 Cephadm 对现有集群的 adopt 能力（据称新版本已有改善）</li><li><strong>Ceph 版本升级</strong>：从 Pacific（v16）升级至更新版本，期望获得更好的慢盘检测与 OSD 自动驱逐能力</li><li><strong>硬件整合</strong>：利用容量升级带来的余量，评估是否可以下线 2019 年前后的旧机器，降低运维成本</li></ol><h2 id="关键经验总结" tabindex="-1">关键经验总结 <a class="header-anchor" href="#关键经验总结" aria-label="Permalink to &quot;关键经验总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>经验</th><th>说明</th></tr></thead><tbody><tr><td>VxLAN 是透明迁移的关键</td><td>保持 IP/主机名不变，Ceph 无感知</td></tr><tr><td>老旧硬件搬移风险高</td><td>故障率显著上升，务必预留余量</td></tr><tr><td>noout + norebalance 组合</td><td>物理迁移阶段必须设置，防止数据迁移风暴</td></tr><tr><td>带锁扣电源线值得投资</td><td>避免因震动导致意外断电</td></tr><tr><td>慢盘问题需关注</td><td>商用硬件慢盘不会自动被驱逐，影响服务质量</td></tr><tr><td>MON 数据库需关注膨胀</td><td>长期非健康状态会导致 trimming 停止</td></tr><tr><td>Deep scrub 积压需人工介入</td><td>大规模运维期间需定期手动清理积压</td></tr></tbody></table>`,50)])])}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
